<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CafeOn · API Console</title>
<style>
:root{color-scheme:dark;--bg:#0b0d10;--panel:#12151a;--line:#29303a;--muted:#8b95a4;--text:#f5f7f9;--orange:#ff713f;--green:#53d18d;--blue:#65a8ff;--red:#ff6b6b;--yellow:#f3ca52}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,#332016 0,transparent 30%),var(--bg);color:var(--text);font:14px Inter,Pretendard,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}.shell{min-height:100vh;display:grid;grid-template-columns:300px minmax(0,1fr)}aside{height:100vh;position:sticky;top:0;border-right:1px solid var(--line);background:#0f1216eF;display:flex;flex-direction:column}.brand{height:72px;display:flex;align-items:center;gap:12px;padding:0 20px;border-bottom:1px solid var(--line)}.mark{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:linear-gradient(135deg,var(--orange),#d84b21);font-weight:900}.brand strong{font-size:16px}.brand small{display:block;color:var(--muted);font-size:11px;margin-top:2px}.search{padding:16px 14px 8px}.search input{width:100%;height:38px;background:#0b0e12;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:0 12px;outline:none}.endpoint-list{overflow:auto;padding:4px 9px 24px}.tag-title{padding:16px 9px 7px;color:#aeb6c2;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.endpoint{border:0;width:100%;background:transparent;color:#c8ced7;display:grid;grid-template-columns:48px minmax(0,1fr);gap:5px;padding:8px 9px;border-radius:8px;text-align:left;cursor:pointer}.endpoint:hover,.endpoint.active{background:#20252d;color:#fff}.path{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font:12px ui-monospace,Consolas,monospace}.method{font-size:10px;font-weight:900}.get{color:var(--green)}.post{color:var(--blue)}.put,.patch{color:var(--yellow)}.delete{color:var(--red)}main{min-width:0}.topbar{height:72px;padding:0 30px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:4;background:#0b0d10c8;backdrop-filter:blur(12px)}.crumb{color:var(--muted)}.crumb b{color:var(--text)}.status{display:flex;gap:8px;align-items:center;font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 0 4px #53d18d18}.workspace{max-width:1500px;margin:auto;padding:28px 30px 50px}.hero{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:22px}.eyebrow{color:#ff9c5f;font-size:11px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.hero h1{font-size:27px;letter-spacing:-.04em;margin:7px 0 6px}.hero p{margin:0;color:var(--muted)}.docs{color:#cbd2dc;border:1px solid var(--line);border-radius:8px;padding:9px 12px;text-decoration:none}.request{display:grid;grid-template-columns:110px minmax(0,1fr) auto;gap:8px;padding:10px;border:1px solid var(--line);border-radius:13px;background:var(--panel);box-shadow:0 18px 60px #0005}.field{background:#0c0f13;color:var(--text);border:1px solid #303741;border-radius:8px;outline:none}.field:focus{border-color:#765340}.request select,.request input{height:44px;padding:0 12px}.request select{font-weight:900}.send{border:0;border-radius:8px;padding:0 24px;background:linear-gradient(135deg,var(--orange),#e7552a);color:white;font-weight:900;cursor:pointer}.send:disabled{opacity:.55}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(380px,.9fr);gap:16px;margin-top:16px}.card{border:1px solid var(--line);border-radius:12px;background:var(--panel);min-width:0;overflow:hidden}.card-head{height:51px;padding:0 16px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.card-head h2{font-size:13px;margin:0}.tabs{display:flex;gap:18px;height:51px}.tab{border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);cursor:pointer}.tab.active{color:var(--text);border-color:var(--orange)}.pane{display:none;padding:16px}.pane.active{display:block}.label{display:flex;justify-content:space-between;color:#c7cdd6;font-size:11px;margin-bottom:8px}.kv-row{display:grid;grid-template-columns:1fr 1.5fr 30px;gap:7px;margin-bottom:7px}.kv-row input{height:36px;padding:0 9px}.remove,.clear{border:0;background:transparent;color:var(--muted);cursor:pointer}.remove{font-size:18px}.add{margin-top:6px;border:1px dashed #39414c;background:transparent;color:#aeb6c2;border-radius:7px;padding:7px 10px;cursor:pointer}.token-row{display:grid;grid-template-columns:1fr auto;gap:8px}.token-row input{height:40px;padding:0 11px}.soft{border:1px solid var(--line);background:#20252c;color:#d9dee5;border-radius:8px;padding:0 12px;cursor:pointer}.hint{color:var(--muted);font-size:11px}.editor{width:100%;min-height:250px;resize:vertical;background:#0c0f13;color:#dce3eb;border:0;outline:0;padding:16px;font:12px/1.65 ui-monospace,Consolas,monospace}.response{min-height:435px;position:relative;background:#0c0f13}.response pre{margin:0;padding:16px;white-space:pre-wrap;word-break:break-word;color:#cbd5df;font:12px/1.65 ui-monospace,Consolas,monospace;max-height:560px;overflow:auto}.empty{position:absolute;inset:0;display:grid;place-content:center;text-align:center;color:#687384}.empty-icon{width:52px;height:52px;border:1px solid #303741;border-radius:16px;margin:0 auto 12px;display:grid;place-items:center;font-size:22px}.metrics{display:flex;gap:14px;align-items:center;color:var(--muted);font-size:11px}.badge{padding:4px 8px;border-radius:99px;background:#213126;color:var(--green);font-weight:900}.section-title{margin:28px 0 10px;color:#aeb6c2;font-size:11px;font-weight:900;letter-spacing:.1em}.history{border:1px solid var(--line);border-radius:11px;overflow:hidden;background:var(--panel)}.history-row{display:grid;grid-template-columns:70px minmax(0,1fr) 70px 80px;gap:8px;padding:12px 15px;border-top:1px solid var(--line);align-items:center;font-size:12px}.history-row:first-child{border:0}.url{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:ui-monospace,monospace}.time{color:var(--muted);text-align:right}@media(max-width:900px){.shell{grid-template-columns:1fr}aside{display:none}.grid{grid-template-columns:1fr}.workspace{padding:22px 16px}.topbar{padding:0 16px}.hero{align-items:flex-start;flex-direction:column}.request{grid-template-columns:94px 1fr}.send{grid-column:1/-1;height:44px}.history-row{grid-template-columns:55px 1fr 55px}.time{display:none}}
</style></head><body>
<div class="shell"><aside><div class="brand"><div class="mark">C</div><div><strong>CafeOn</strong><small>API Console · v2.0</small></div></div><div class="search"><input id="search" placeholder="엔드포인트 검색"></div><div id="endpointList" class="endpoint-list"><div class="tag-title">명세 불러오는 중...</div></div></aside>
<main><div class="topbar"><div class="crumb">Workspace / <b>API Tester</b></div><div class="status"><i class="dot"></i> Local server</div></div><div class="workspace">
<div class="hero"><div><div class="eyebrow">Developer workspace</div><h1>API를 빠르게 실행하고 확인하세요.</h1><p>왼쪽 명세에서 고르거나 요청 URL을 직접 입력할 수 있습니다.</p></div><a class="docs" href="/api/documentation" target="_blank">API 문서 ↗</a></div>
<form id="requestForm" class="request"><select id="method" class="field"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select><input id="url" class="field" value="/api/stores" autocomplete="off"><button id="send" class="send">요청 보내기　⌘↵</button></form>
<div class="grid"><section class="card"><div class="card-head"><div class="tabs"><button class="tab active" data-pane="params" type="button">Params</button><button class="tab" data-pane="auth" type="button">Auth</button><button class="tab" data-pane="headers" type="button">Headers</button><button class="tab" data-pane="body" type="button">Body</button></div></div>
<div id="params" class="pane active"><div class="label">QUERY PARAMETERS</div><div id="paramsRows"></div><button class="add" data-add="params" type="button">+ 파라미터 추가</button></div>
<div id="auth" class="pane"><div class="label">BEARER TOKEN</div><div class="token-row"><input id="token" class="field" type="password" placeholder="로그인 응답의 token"><button id="toggleToken" class="soft" type="button">보기</button></div><p class="hint">토큰은 이 브라우저에만 저장되며 Authorization 헤더로 전송됩니다.</p></div>
<div id="headers" class="pane"><div class="label">REQUEST HEADERS</div><div id="headersRows"></div><button class="add" data-add="headers" type="button">+ 헤더 추가</button></div>
<div id="body" class="pane"><div class="label"><span>JSON BODY</span><button id="format" class="clear" type="button">정렬</button></div><textarea id="bodyEditor" class="editor" spellcheck="false">{}</textarea></div></section>
<section class="card"><div class="card-head"><h2>Response</h2><div id="metrics" class="metrics"></div></div><div class="response"><div id="empty" class="empty"><div><div class="empty-icon">⌁</div><b>응답 대기 중</b><p>요청을 보내면 결과가 여기에 표시됩니다.</p></div></div><pre id="response"></pre></div></section></div>
<div class="section-title">RECENT REQUESTS</div><section class="history"><div class="card-head"><h2>요청 기록</h2><button id="clearHistory" class="clear">모두 지우기</button></div><div id="history"></div></section>
</div></main></div>
<script>
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],state={endpoints:[],history:JSON.parse(localStorage.getItem('cafeon-api-history')||'[]')};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function addRow(t,k='',v=''){const r=document.createElement('div');r.className='kv-row';r.innerHTML='<input class="field key" placeholder="Key"><input class="field value" placeholder="Value"><button class="remove" type="button">×</button>';r.querySelector('.key').value=k;r.querySelector('.value').value=v;r.querySelector('button').onclick=()=>r.remove();$('#'+t+'Rows').append(r)}function vals(t){return [...$('#'+t+'Rows').children].map(r=>[r.querySelector('.key').value.trim(),r.querySelector('.value').value]).filter(x=>x[0])}
function sample(s){if(!s)return{};if(s.example!==undefined)return s.example;if(s.type==='array')return[sample(s.items)];const o={};for(const[k,v]of Object.entries(s.properties||{}))o[k]=v.example??v.default??({string:'',integer:0,number:0,boolean:false,array:[],object:{}}[v.type]??'');return o}
async function loadSpec(){try{const r=await fetch('/docs');if(!r.ok)throw Error();const spec=await r.json();for(const[path,ops]of Object.entries(spec.paths||{}))for(const[method,op]of Object.entries(ops))if(['get','post','put','patch','delete'].includes(method))state.endpoints.push({path,method,op,tag:(op.tags||['Other'])[0]});renderEndpoints()}catch{$('#endpointList').innerHTML='<div class="tag-title">API 명세를 불러오지 못했습니다</div>'}}
function renderEndpoints(q=''){const list=state.endpoints.filter(e=>(e.path+' '+e.method+' '+e.tag+' '+(e.op.summary||'')).toLowerCase().includes(q.toLowerCase())),groups=list.reduce((a,e)=>((a[e.tag]??=[]).push(e),a),{});$('#endpointList').innerHTML=Object.entries(groups).map(([tag,x])=>'<div class="tag-title">'+esc(tag)+' · '+x.length+'</div>'+x.map(e=>'<button class="endpoint" data-path="'+esc(e.path)+'" data-method="'+e.method+'"><span class="method '+e.method+'">'+e.method.toUpperCase()+'</span><span class="path">'+esc(e.path.replace('/api/','/'))+'</span></button>').join('')).join('')||'<div class="tag-title">검색 결과 없음</div>';$$('.endpoint').forEach(b=>b.onclick=()=>selectEndpoint(b.dataset.path,b.dataset.method))}
function selectEndpoint(path,method){$('.endpoint.active')?.classList.remove('active');$$('.endpoint').find(b=>b.dataset.path===path&&b.dataset.method===method)?.classList.add('active');$('#method').value=method.toUpperCase();$('#url').value=path;const e=state.endpoints.find(x=>x.path===path&&x.method===method);$('#paramsRows').innerHTML='';for(const p of e?.op.parameters||[])if(p.in==='query')addRow('params',p.name,p.example??p.schema?.default??'');$('#bodyEditor').value=JSON.stringify(sample(e?.op.requestBody?.content?.['application/json']?.schema),null,2)}
function renderHistory(){$('#history').innerHTML=state.history.length?state.history.map(h=>'<div class="history-row"><b class="method '+h.method.toLowerCase()+'">'+h.method+'</b><span class="url">'+esc(h.url)+'</span><span class="badge" style="'+(h.ok?'':'color:var(--red);background:#352124')+'">'+h.status+'</span><span class="time">'+h.ms+' ms</span></div>').join(''):'<div style="padding:22px;color:var(--muted);text-align:center">아직 요청 기록이 없습니다.</div>'}
async function send(e){e?.preventDefault();const method=$('#method').value,input=$('#url').value.trim();if(!input)return;const url=new URL(input,location.origin),headers={Accept:'application/json'};for(const[k,v]of vals('params'))url.searchParams.set(k,v);for(const[k,v]of vals('headers'))headers[k]=v;const token=$('#token').value.trim();if(token)headers.Authorization='Bearer '+token;const opts={method,headers};if(!['GET','HEAD'].includes(method)){headers['Content-Type']=headers['Content-Type']||'application/json';if($('#bodyEditor').value.trim())opts.body=$('#bodyEditor').value.trim()}$('#send').disabled=true;$('#send').textContent='요청 중…';$('#empty').style.display='none';$('#response').textContent='';const start=performance.now();try{const res=await fetch(url,opts),ms=Math.round(performance.now()-start),text=await res.text();let out=text;try{out=JSON.stringify(JSON.parse(text),null,2)}catch{}$('#response').textContent=out||'(empty response)';$('#metrics').innerHTML='<span class="badge" style="'+(res.ok?'':'color:var(--red);background:#352124')+'">'+res.status+' '+esc(res.statusText)+'</span><span>'+ms+' ms</span><span>'+new Blob([text]).size+' B</span>';state.history.unshift({method,url:url.pathname+url.search,status:res.status,ok:res.ok,ms});state.history=state.history.slice(0,8);localStorage.setItem('cafeon-api-history',JSON.stringify(state.history));renderHistory()}catch(err){$('#response').textContent='Request failed\n\n'+err.message;$('#metrics').innerHTML='<span class="badge" style="color:var(--red);background:#352124">NETWORK ERROR</span>'}finally{$('#send').disabled=false;$('#send').textContent='요청 보내기　⌘↵'}}
$$('.tab').forEach(t=>t.onclick=()=>{$$('.tab,.pane').forEach(x=>x.classList.remove('active'));t.classList.add('active');$('#'+t.dataset.pane).classList.add('active')});$$('[data-add]').forEach(b=>b.onclick=()=>addRow(b.dataset.add));$('#search').oninput=e=>renderEndpoints(e.target.value);$('#requestForm').onsubmit=send;$('#format').onclick=()=>{try{$('#bodyEditor').value=JSON.stringify(JSON.parse($('#bodyEditor').value),null,2)}catch{alert('올바른 JSON 형식이 아닙니다.')}};$('#toggleToken').onclick=()=>{const x=$('#token');x.type=x.type==='password'?'text':'password';$('#toggleToken').textContent=x.type==='password'?'보기':'숨기기'};$('#token').value=localStorage.getItem('cafeon-api-token')||'';$('#token').oninput=e=>localStorage.setItem('cafeon-api-token',e.target.value);$('#clearHistory').onclick=()=>{state.history=[];localStorage.removeItem('cafeon-api-history');renderHistory()};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')send(e)});addRow('params');addRow('headers');renderHistory();loadSpec();
</script></body></html>
